<script setup lang="ts">import{onBeforeUnmount,onMounted,ref}from"vue";import{onBeforeRouteLeave,useRoute,useRouter}from"vue-router";import BaseEmptyState from"@/components/base/BaseEmptyState.vue";import BasePageHeader from"@/components/base/BasePageHeader.vue";import VodForm from"@/features/vod/components/VodForm.vue";import type{VodFormData}from"@/domain/vod/models";import{mapAvailabilityToForm,mapVodFormToPayload}from"@/domain/vod/mapper";import{availabilityRepository}from"@/domain/repositories";const route=useRoute(),router=useRouter(),id=String(route.params.id),initial=ref<VodFormData|null>(null),loading=ref(true),saving=ref(false),dirty=ref(false),error=ref("");let allow=false;async function load(){loading.value=true;try{initial.value=mapAvailabilityToForm(await availabilityRepository.get(id))}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}async function save(f:VodFormData){saving.value=true;error.value="";try{await availabilityRepository.update(id,mapVodFormToPayload(f));allow=true;dirty.value=false;await router.push({name:"vod",query:{updated:"1"}})}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{saving.value=false}}function before(e:BeforeUnloadEvent){if(!dirty.value)return;e.preventDefault();e.returnValue=""}onBeforeRouteLeave(()=>allow||!dirty.value||window.confirm("Existem alterações por guardar. Queres sair sem guardar?"));onMounted(()=>{window.addEventListener("beforeunload",before);void load()});onBeforeUnmount(()=>window.removeEventListener("beforeunload",before));</script><template><section v-if="loading" class="page-loading"><span class="loader"/></section><BaseEmptyState v-else-if="error&&!initial" icon="!" title="Não foi possível abrir a disponibilidade" :description="error"><button class="button button-secondary" @click="load">Voltar a tentar</button></BaseEmptyState><template v-else-if="initial"><BasePageHeader eyebrow="VOD" title="Editar disponibilidade" description="Atualiza provider, modalidade, país, preço e validade."/><div v-if="error" class="form-alert form-alert-error">{{error}}</div><VodForm :initial-value="initial" :saving="saving" submit-label="Guardar alterações" @dirty-change="dirty=$event" @submit="save"/></template></template>
